        FastScanner scanner = new FastScanner(System.in);
        int L = scanner.nextInt();
        int C = scanner.nextInt();

        int[][] A = new int[L][C];
        for (int i = 0; i < L; i++) {
            for (int j = 0; j < C; j++) {
                A[i][j] = scanner.nextInt();
            }
        }

        int R = L - 1;
        int K = C - 1;
        int[][] B = new int[R][K];
        for (int i = 0; i < R; i++) {
            for (int j = 0; j < K; j++) {
                if ((long) A[i][j] + A[i + 1][j + 1] <= (long) A[i][j + 1] + A[i + 1][j]) {
                    B[i][j] = 1;
                } else {
                    B[i][j] = 0;
                }
            }
        }

        int[] height = new int[K];
        int[] stack = new int[K + 1];
        long maxArea = 0;

        for (int i = 0; i < R; i++) {
            for (int j = 0; j < K; j++) {
                if (B[i][j] == 1) {
                    height[j]++;
                } else {
                    height[j] = 0;
                }
            }

            int top = 0;
            for (int j = 0; j <= K; j++) {
                int curH = (j == K) ? 0 : height[j];
                while (top > 0 && curH < height[stack[top - 1]]) {
                    int h = height[stack[--top]];
                    int left = (top == 0) ? 0 : stack[top - 1] + 1;
                    int w = j - left;
                    long area = (long) (h + 1) * (w + 1);
                    if (area > maxArea) {
                        maxArea = area;
                    }
                }
                stack[top++] = j;
            }
        }

        System.out.println(maxArea);
    }

    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0;
        private int len = 0;

        public FastScanner(InputStream in) {
            this.in = in;
        }

        private int readByte() throws IOException {
            if (ptr >= len) {
                ptr = 0;
                len = in.read(buffer);
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        public int nextInt() throws IOException {
            int c = readByte();
            while (c <= ' ' && c != -1) {
                c = readByte();
            }
            if (c == -1) return 0;
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = readByte();
            }
            int res = 0;
            while (c >= '0' && c <= '9') {
                res = res * 10 + (c - '0');
                c = readByte();
            }
            return res * sign;
        }
    }
}
